. "$PSScriptRoot/scripts-common.ps1"
if (-not $SkipBuild) { & "$PSScriptRoot/build.ps1" }
$godot = Find-Godot
$gameArguments = @('--play', '--capture', "--view=$View")
if ($Seed -gt 0) { $gameArguments += "--seed=$Seed" }
$playArguments = @()
if ($GodMode) { $playArguments = @('--', '--god-mode') }
if ($Capture) { & $godot --path $PSScriptRoot -- $gameArguments }
# The game itself runs fullscreen (Godot's borderless fullscreen window); -Windowed keeps the window of project.godot.
# -GodMode (god-mode.bat) lets Shift make the car five times faster; the game keeps using the player's save.
elseif ($Windowed) { & $godot --path $PSScriptRoot @playArguments }
else { & $godot --path $PSScriptRoot --fullscreen @playArguments }
Assert-ExitCode 'Spuštění'
